// Ships one half of the product and says where it landed.
//
// The site is static, so the API's origin is baked into it at build time — and for a long
// time that meant the first deploy could not work: the Worker did not exist yet, so nobody
// could know its origin, so a human pasted it in between two runs. Nothing about that was
// necessary. Both origins are knowable the moment their half is deployed: the Worker's from
// what `wrangler deploy` prints, the site's from the Pages project itself. So this deploys,
// reads the origin back, and hands it to the next step.
//
// A custom domain in front of either is the one thing that cannot be derived — set the
// `API_ORIGIN` or `SITE_ORIGIN` repository variable and it wins over what is read back.
//
// Usage: `node dev/tools/deploy.ts api` | `node dev/tools/deploy.ts site`
import { appendFileSync } from 'node:fs';
import { PAGES_PROJECT, wrangler } from './cloudflare.ts';

const half = process.argv[2];
if (half !== 'api' && half !== 'site') {
  console.error('deploy: takes "api" or "site"');
  process.exit(2);
}

/** Every origin carries how it was found, because "derived" and "overridden" fail differently. */
type Origin = { url: string; how: string };

const override = (name: string): Origin | null => {
  const value = process.env[name]?.trim().replace(/\/+$/, '');
  return value ? { url: value, how: `the ${name} repository variable` } : null;
};

const hostIn = (output: string, suffix: string): string | undefined =>
  output.match(new RegExp(`https://[a-z0-9-]+(?:\\.[a-z0-9-]+)*\\.${suffix.replace('.', '\\.')}`, 'i'))?.[0];

function deployApi(): Origin {
  const run = wrangler(['deploy'], 600_000);
  console.log(run.output);
  if (!run.ok) {
    console.error(`::error::wrangler deploy failed — ${run.reason}`);
    process.exit(1);
  }
