1	// Creates whatever production is missing. The counterpart to the preflight: same table of
2	// resources, same question asked of Cloudflare — but where the preflight reports a `MISS`,
3	// this creates the thing.
4	//
5	// Every resource hitbut needs is one non-interactive `wrangler … create`, so none of this
6	// needs the dashboard; what needs a human is the account, the API token and the decision to
7	// spend money in that account, which is why this runs from a `workflow_dispatch` rather than
8	// on its own.
9	//
10	// Two rules it will not break:
11	//
12	//   * **It creates only on a confirmed absence.** A resource we could not ask about (a token
13	//     scope, a renamed command, a refused network) is left alone and reported, because
14	//     creating a second copy of something that is already there is worse than stopping.
15	//   * **It never guesses a shape that cannot be changed later.** A Vectorize index fixes its
16	//     dimension count at creation, so without an explicit `VECTORIZE_DIMENSIONS` it declines
17	//     rather than pick one.
18	//
19	// Usage: `npm run provision` (creates), `npm run provision -- --dry-run` (says what it would).
20	import { readFileSync, writeFileSync } from 'node:fs';
21	import { fileURLToPath } from 'node:url';
22	import { D1_DATABASE, RESOURCES, decide, look, wrangler } from './cloudflare.ts';
23	
24	const WRANGLER_TOML = fileURLToPath(new URL('../../wrangler.toml', import.meta.url));
25	const PLACEHOLDER_DATABASE_ID = '00000000-0000-0000-0000-000000000000';
26	const dryRun = process.argv.includes('--dry-run');
27	
28	type Outcome = 'already there' | 'created' | 'would create' | 'declined' | 'failed';
29	const results: { label: string; outcome: Outcome; detail: string }[] = [];
30	const record = (label: string, outcome: Outcome, detail = '') => {
31	  results.push({ label, outcome, detail });
32	  console.log(`  [${outcome.padEnd(12)}] ${label}${detail ? ` — ${detail}` : ''}`);
33	};
34	
35	console.log('\nhitbut provision — creates what production is missing, and nothing else\n');
36	if (dryRun) console.log('  (dry run: nothing will be created)\n');
37	
38	for (const resource of RESOURCES) {
39	  const state = look(resource);
40	  const decision = decide(resource, state);
41	  if (decision.act === 'leave') {
42	    record(resource.label, state.state === 'present' ? 'already there' : 'declined', decision.why);
43	    continue;
44	  }
45	  if (dryRun) {
46	    record(resource.label, 'would create', decision.why);
47	    continue;
48	  }
49	  const run = wrangler(resource.create);
50	  record(resource.label, run.ok ? 'created' : 'failed', run.ok ? '' : run.reason);
51	}
52	
53	/**
54	 * The one piece of production that lives in the repo rather than in the account: D1 hands
55	 * out the id when it creates the database, and `wrangler deploy` reads it from the committed
56	 * config. Resolving it from the database's own name keeps this true whoever created it —
57	 * a run against an account provisioned by hand writes the same line.
58	 */
59	function pinDatabaseId(): void {
60	  const toml = readFileSync(WRANGLER_TOML, 'utf8');
61	  const pinned = /database_id\s*=\s*"([^"]+)"/.exec(toml)?.[1];
62	  if (pinned && pinned !== PLACEHOLDER_DATABASE_ID) {
63	    record('wrangler.toml database_id', 'already there', `pinned to ${pinned}`);
64	    return;
65	  }
66	
67	  const listed = wrangler(['d1', 'list', '--json'], 90_000);
68	  if (!listed.ok) {
69	    record('wrangler.toml database_id', 'declined', `could not read the id back — ${listed.reason}`);
70	    return;
71	  }
72	  let uuid: string | undefined;
73	  try {
74	    const databases = JSON.parse(listed.output.slice(listed.output.indexOf('['))) as {
75	      uuid?: string;
76	      name?: string;
77	    }[];
78	    uuid = databases.find((database) => database.name === D1_DATABASE)?.uuid;
79	  } catch (error) {
80	    record('wrangler.toml database_id', 'failed', `\`d1 list --json\` did not parse: ${(error as Error).message}`);
81	    return;
82	  }
83	  if (!uuid) {
84	    record('wrangler.toml database_id', 'declined', `${D1_DATABASE} is not in the account's list yet`);
85	    return;
86	  }
87	  if (dryRun) {
88	    record('wrangler.toml database_id', 'would create', `would pin ${uuid}`);
89	    return;
90	  }
91	  writeFileSync(WRANGLER_TOML, toml.replace(PLACEHOLDER_DATABASE_ID, uuid));
92	  record('wrangler.toml database_id', 'created', `pinned to ${uuid} — commit this`);
93	}
94	
95	pinDatabaseId();
96	
97	const failed = results.filter((result) => result.outcome === 'failed');
98	const declined = results.filter((result) => result.outcome === 'declined');
99	
100	console.log('');
101	if (declined.length) {
102	  console.log(
103	    `${declined.length} item(s) declined. Declining is deliberate: an unanswered question or an ` +
104	      'undecided shape is not the same as an absent resource, and creating on either is the mistake ' +
105	      'this refuses to make.',
106	  );
107	}
108	if (failed.length) {
109	  console.log(`\nFailed: ${failed.map((result) => result.label).join(', ')}`);
110	  process.exit(1);
111	}
112	console.log('\nRun the preflight to see production as it now stands.\n');

