1	// Provisioning creates things in someone's Cloudflare account and reads back where they
2	// landed, and neither half can be exercised here — there is no account to run against. What
3	// *can* be held is the reasoning either half does before it acts: when the provisioner is
4	// allowed to create, and how an origin is read out of what a deploy printed.
5	//
6	// The refusals are the point. Creating a resource because a token scope stopped us asking
7	// about it, or creating a Vectorize index on a guessed dimension count, are both mistakes
8	// nobody sees until much later — an index's dimensions cannot be changed afterwards.
9	import test from 'node:test';
10	import assert from 'node:assert/strict';
11	import {
12	  PAGES_PROJECT,
13	  RESOURCES,
14	  VECTORIZE_INDEX,
15	  decide,
16	  firstUsefulLine,
17	  missing,
18	  present,
19	  unknown,
20	} from '../tools/cloudflare.ts';
21	import { deployedSite, deployedWorker, overrideFrom, projectSite } from '../tools/origins.ts';
22	
23	const resource = (name: string) => {
24	  const found = RESOURCES.find((candidate) => candidate.name === name);
25	  assert.ok(found, `no resource named ${name} — has the table changed shape?`);
26	  return found;
27	};
28	
29	test('a resource Cloudflare says is absent is created', () => {
30	  const bucket = resource('hitbut-raw');
31	  assert.deepEqual(decide(bucket, missing('hitbut-raw is not in the list')).act, 'create');
32	});
33	
34	test('a resource that is already there is left alone', () => {
35	  assert.equal(decide(resource('hitbut-raw'), present('found')).act, 'leave');
36	});
37	
38	test('a question that could not be asked is never read as an absence', () => {
39	  const decision = decide(resource('hitbut-raw'), unknown('`wrangler r2 bucket list` failed — bad token'));
40	  assert.equal(decision.act, 'leave');
41	  assert.match(decision.why, /could not be asked/);
42	});
43	
44	test('the Vectorize index is not created on a guessed dimension count', () => {
45	  assert.equal(process.env.VECTORIZE_DIMENSIONS, undefined, 'this test states what happens when it is unset');
46	  const decision = decide(resource(VECTORIZE_INDEX), missing('not in the list'));
47	  assert.equal(decision.act, 'leave');
48	  assert.match(decision.why, /dimensions at creation/);
49	});
50	
51	test('every create command names the resource the check looks for', () => {
52	  for (const candidate of RESOURCES) {
53	    assert.ok(
54	      candidate.create.includes(candidate.name),
55	      `${candidate.label} would create something other than what the preflight looks for`,
56	    );
57	  }
58	});
59	
60	test('creating the Pages project cannot stop to ask a question', () => {
61	  // A prompt on a runner is a hang, not a failure. --production-branch is what removes it.
62	  assert.ok(resource(PAGES_PROJECT).create.includes('--production-branch'));
63	});
64	
65	test("the Worker's origin is read out of what wrangler printed", () => {
66	  const output = [
67	    'Total Upload: 92.41 KiB / gzip: 20.11 KiB',
68	    'Uploaded hitbut-api (3.90 sec)',
69	    'Deployed hitbut-api triggers (0.31 sec)',
70	    '  https://hitbut-api.missingbulb.workers.dev',
71	    'Current Version ID: 7f6b…',
72	  ].join('\n');
73	  assert.equal(deployedWorker(output)?.url, 'https://hitbut-api.missingbulb.workers.dev');
74	});
75	
76	test("colour codes do not hide the Worker's origin", () => {
77	  const output = `[32m  https://hitbut-api.missingbulb.workers.dev[0m`;
78	  assert.equal(deployedWorker(output)?.url, 'https://hitbut-api.missingbulb.workers.dev');
79	});
80	
81	test('a deploy that printed no origin is a failure, not an empty string', () => {
82	  assert.equal(deployedWorker('Uploaded hitbut-api (3.90 sec)'), null);
83	});
84	
85	test('a repository variable wins over what was read back', () => {
86	  assert.equal(overrideFrom('API_ORIGIN', 'https://api.hitbut.example/')?.url, 'https://api.hitbut.example');
87	  assert.equal(overrideFrom('API_ORIGIN', '  '), null);
88	  assert.equal(overrideFrom('API_ORIGIN', undefined), null);
89	});
90	
91	test("the site's origin is the project's own host, not the deployment's alias", () => {
92	  const listed = JSON.stringify([{ name: 'other', subdomain: 'other.pages.dev' }, { name: PAGES_PROJECT, subdomain: 'hitbut.pages.dev' }]);
93	  assert.equal(projectSite(listed, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
94	});
95	
96	test("wrangler's own warnings do not get read as the list", () => {
97	  // `--json` output arrives with the banner and any warnings around it, and `[WARNING]` is a
98	  // bracket too — the first `[` in the output is routinely not the list.
99	  const noisy = [
100	    ' ⛅️ wrangler 4.125.0',
101	    '▲ [WARNING] Proxy environment variables detected.',
102	    JSON.stringify([{ name: PAGES_PROJECT, subdomain: 'hitbut.pages.dev' }]),
103	  ].join('\n');
104	  assert.equal(projectSite(noisy, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
105	});
106	
107	test('a Pages listing that cannot be read is not an origin', () => {
108	  assert.equal(projectSite('Authentication error', PAGES_PROJECT), null);
109	  assert.equal(projectSite(JSON.stringify([{ name: 'somebody-else' }]), PAGES_PROJECT), null);
110	});
111	
112	test("falling back to the deployment URL strips the per-deployment label", () => {
113	  const output = '✨ Deployment complete! Take a peek over at https://a1b2c3d4.hitbut.pages.dev';
114	  assert.equal(deployedSite(output, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
115	});
116	
117	test('a deployment URL for another project is not our site', () => {
118	  assert.equal(deployedSite('https://a1b2c3d4.something-else.pages.dev', PAGES_PROJECT), null);
119	});
120	
121	test("wrangler's own error line is what gets reported, not its banner", () => {
122	  const output = [
123	    ' ⛅️ wrangler 4.125.0',
124	    '▲ [WARNING] Proxy environment variables detected.',
125	    '✘ [ERROR] Authentication error [code: 10000]',
126	  ].join('\n');
127	  assert.equal(firstUsefulLine(output), 'Authentication error [code: 10000]');
128	});

