1	// Provisioning creates things in someone's Cloudflare account and reads back where they
2	// landed, and neither half can be exercised here — there is no account to run against. What
3	// *can* be held is the reasoning either half does before it acts: when the provisioner is
4	// allowed to create, and how an origin is read out of what a deploy printed.
5	//
6	// The refusals are the point. Creating a resource because a token scope stopped us asking
7	// about it, or creating a Vectorize index on a guessed dimension count, are both mistakes
8	// nobody sees until much later — an index's dimensions cannot be changed afterwards.
9	import test from 'node:test';
10	import assert from 'node:assert/strict';
11	import {
12	  ALLOWED,
13	  PAGES_PROJECT,
14	  PLACEHOLDER_DATABASE_ID,
15	  RESOURCES,
16	  VECTORIZE_INDEX,
17	  assertSafe,
18	  decide,
19	  firstUsefulLine,
20	  missing,
21	  present,
22	  unknown,
23	  withDatabaseId,
24	} from '../tools/cloudflare.ts';
25	import { deployedSite, deployedWorker, overrideFrom, projectSite } from '../tools/origins.ts';
26	
27	const resource = (name: string) => {
28	  const found = RESOURCES.find((candidate) => candidate.name === name);
29	  assert.ok(found, `no resource named ${name} — has the table changed shape?`);
30	  return found;
31	};
32	
33	test('a resource Cloudflare says is absent is created', () => {
34	  const bucket = resource('hitbut-raw');
35	  assert.deepEqual(decide(bucket, missing('hitbut-raw is not in the list')).act, 'create');
36	});
37	
38	test('a resource that is already there is left alone', () => {
39	  assert.equal(decide(resource('hitbut-raw'), present('found')).act, 'leave');
40	});
41	
42	test('a question that could not be asked is never read as an absence', () => {
43	  const decision = decide(resource('hitbut-raw'), unknown('`wrangler r2 bucket list` failed — bad token'));
44	  assert.equal(decision.act, 'leave');
45	  assert.match(decision.why, /could not be asked/);
46	});
